1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { basename, dirname, join, relative, resolve } from 'pathe';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	import { WITNESS_CANCELLED_DUPLICATE_FETCH_RULE } from '../../../core/src/receipts/witness-real-app.ts';
5	import {
6		ANGULAR_FACTORIOLAB_CANONICAL_RECEIPTS,
7		ANGULAR_FACTORIOLAB_FIXTURE,
8		ANGULAR_FACTORIOLAB_SOURCE,
9		parseWitnessAngularFactoriolabReceipt,
10		renderWitnessAngularFactoriolabReceipt,
11		WITNESS_ANGULAR_FACTORIOLAB_CANCELLED_DUPLICATE_FETCHES,
12		WITNESS_ANGULAR_FACTORIOLAB_CONSOLE_ERRORS,
13		WITNESS_ANGULAR_FACTORIOLAB_FAILED_REQUESTS,
14		WITNESS_ANGULAR_FACTORIOLAB_SCHEMA,
15		WITNESS_ANGULAR_FACTORIOLAB_SERVICE_WORKER,
16		witnessAngularFactoriolabBehaviorDigest,
17		witnessAngularFactoriolabDigest,
18		witnessAngularFactoriolabRawDigest,
19		type WitnessAngularFactoriolabMutation,
20		type WitnessAngularFactoriolabReceipt,
21		type WitnessAngularFactoriolabRun,
22	} from '../../../core/src/receipts/witness-angular-factoriolab.ts';
23	import { executeAngularFactoriolabWitnessRun, FACTORIOLAB_MUTATION_SEAM } from './real-app-run.ts';
24	import { verifyLinkedWitnessProvenance } from './provenance.ts';
25	
26	const root = resolve(import.meta.dirname, '../../../..');
27	const fixtureEvidence = join(root, 'evidence/runs/angular-factoriolab');
28	const witnessEvidence = join(root, 'evidence/runs/witness-angular-factoriolab');
29	const stageRoot = join(root, '.versionless/stage/witness-angular-factoriolab');
30	/**
31	 * The two committed build lanes: the era baseline rebuilt on its own Angular 10
32	 * cell, and the migrated Angular 16.2 browser-builder output. Both are produced
33	 * offline by `packages/cli/src/fixture/angular-factoriolab-build-lanes-run.ts`.
34	 */
35	const sourceOutputs = {
36		baseline: join(root, '.versionless/cache/angular-factoriolab-baseline/rebuild/dist-1'),
37		migrated: join(root, '.versionless/stage/angular-factoriolab-m2/dist-a'),
38	} as const;
39	const laneFileCounts = { baseline: 42, migrated: 39 } as const;
40	
41	async function exists(path: string): Promise<boolean> {
42		return access(path).then(
43			() => true,
44			() => false,
45		);
46	}
47	
48	async function files(directory: string): Promise<string[]> {
49		const output: string[] = [];
50		for (const entry of await readdir(directory, { withFileTypes: true })) {
51			const path = join(directory, entry.name);
52			if (entry.isDirectory()) output.push(...(await files(path)));
53			else if (entry.isFile()) output.push(path);
54		}
55		return output.sort();
56	}
57	
58	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
59		const lanes = join(stageRoot, 'lanes');
60		await rm(lanes, { recursive: true, force: true });
61		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
62		for (const lane of ['baseline', 'migrated'] as const) {
63			if (!(await exists(sourceOutputs[lane])))
64				throw new Error(`factoriolab ${lane} production output is absent`);
65			await mkdir(dirname(staged[lane]), { recursive: true });
66			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
67			const staged_files = await files(staged[lane]);
68			if (staged_files.length !== laneFileCounts[lane])
69				throw new Error(
70					`factoriolab ${lane} lane file count differs: ${staged_files.length} against ${laneFileCounts[lane]}`,
71				);
72		}
73		return staged;
74	}
75	
76	async function executeRuns(
77		lanes: Record<'baseline' | 'migrated', string>,
78	): Promise<WitnessAngularFactoriolabRun[]> {
79		const runs: WitnessAngularFactoriolabRun[] = [];
80		for (const lane of ['baseline', 'migrated'] as const)
81			for (const pass of [1, 2] as const) {
82				const raw = await executeAngularFactoriolabWitnessRun({
83					lane,
84					pass,
85					laneRoot: lanes[lane],
86					receiptRoot: join(stageRoot, 'receipts'),
87				});
88				const run = raw as WitnessAngularFactoriolabRun;
89				if (run.semanticDigest !== witnessAngularFactoriolabRawDigest(run))
90					throw new Error(`factoriolab ${lane} pass ${pass} raw digest differs`);
91				runs.push({ ...run, behaviorDigest: witnessAngularFactoriolabBehaviorDigest(run) });
92			}
93		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
94			throw new Error('factoriolab baseline/migrated behavior parity differs');
95		return runs;
96	}
97	
98	/**
99	 * Byte mutation on the migrated build: locate the visible columns-dialog title
100	 * in the served module, overwrite it in place with an equal-length filler,
101	 * require the journey to go red on that exact assertion, restore the original
102	 * bytes, and require the restored journey to reproduce the parity behavior
103	 * digest.
104	 */
105	async function semanticMutation(
106		laneRoot: string,
107		behaviorDigest: string,
108	): Promise<WitnessAngularFactoriolabMutation> {
109		const expected = Buffer.from(FACTORIOLAB_MUTATION_SEAM);
110		const candidates: Array<{ path: string; offset: number }> = [];
111		for (const path of await files(laneRoot)) {
112			const bytes = await readFile(path);
113			const offset = bytes.indexOf(expected);
114			if (offset < 0) continue;
115			if (bytes.lastIndexOf(expected) !== offset)
116				throw new Error('factoriolab semantic seam is not unique within its file');
117			candidates.push({ path, offset });
118		}
119		const target = candidates[0];
120		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
121			throw new Error('factoriolab semantic seam is not a single served module');
122		const before = await readFile(target.path);
123		const mutated = Buffer.from(before);
124		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
125		const beforeSha256 = sha256(before);
126		const mutatedSha256 = sha256(mutated);
127		let intendedFailure = false;
128		try {
129			await writeFile(target.path, mutated);
130			try {
131				await executeAngularFactoriolabWitnessRun({
132					lane: 'migrated',
133					pass: 1,
134					laneRoot,
135					receiptRoot: join(stageRoot, 'mutation-receipt'),
136				});
137			} catch (error) {
138				const message = error instanceof Error ? error.message : String(error);
139				intendedFailure = message.includes(FACTORIOLAB_MUTATION_SEAM);
140			}
141		} finally {
142			await writeFile(target.path, before);
143		}
144		const afterRestoreSha256 = sha256(await readFile(target.path));
145		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
146			throw new Error('factoriolab semantic mutation was not exact red and byte-restored');
147		const restored = (await executeAngularFactoriolabWitnessRun({
148			lane: 'migrated',
149			pass: 1,
150			laneRoot,
151			receiptRoot: join(stageRoot, 'restoration-receipt'),
152		})) as WitnessAngularFactoriolabRun;
153		const restoredBehaviorDigest = witnessAngularFactoriolabBehaviorDigest(restored);
154		if (restoredBehaviorDigest !== behaviorDigest)
155			throw new Error('factoriolab restored browser behavior differs');
156		return {
157			failure: 'witness-semantic-assertion',
158			intendedFailure: true,
159			lane: 'migrated',
160			seam: FACTORIOLAB_MUTATION_SEAM,
161			path: relative(laneRoot, target.path),
162			offset: target.offset,
163			beforeSha256,
164			mutatedSha256,
165			afterRestoreSha256,
166			restoredByteIdentically: true,
167			restoredRun: 'pass',
168			restoredBehaviorDigest,
169		};
170	}
171	
172	async function bindCanonicalReceipts(): Promise<
173		WitnessAngularFactoriolabReceipt['canonicalReceipts']
174	> {
175		return await Promise.all(
176			ANGULAR_FACTORIOLAB_CANONICAL_RECEIPTS.map(async (pinned) => {
177				const bytes = await readFile(join(root, pinned.path));
178				const value = JSON.parse(bytes.toString('utf8')) as {
179					schemaVersion?: unknown;
180					digest?: unknown;
181				};
182				if (
183					value.schemaVersion !== pinned.schemaVersion ||
184					value.digest !== pinned.digest ||
185					sha256(bytes) !== pinned.sha256
186				)
187					throw new Error(`factoriolab bound build receipt identity differs: ${pinned.path}`);
188				return {
189					path: pinned.path,
190					schemaVersion: pinned.schemaVersion,
191					digest: pinned.digest,
192					sha256: pinned.sha256,
193				};
194			}),
195		);
196	}
197	
198	export async function runWitnessAngularFactoriolab(): Promise<WitnessAngularFactoriolabReceipt> {
199		if (
200			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
201			process.env.NPM_CONFIG_OFFLINE !== 'true'
202		)
203			throw new Error('factoriolab Witness requires dual offline controls');
204		if (await exists(witnessEvidence)) throw new Error('factoriolab Witness output collision');
205		const provenance = await verifyLinkedWitnessProvenance(root);
206		const canonicalReceipts = await bindCanonicalReceipts();
207		const lanes = await stageInputs();
208		const runs = await executeRuns(lanes);
209		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
210		const artifacts = join(fixtureEvidence, 'artifacts');
211		await mkdir(artifacts, { recursive: true });
212		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
213			flag: 'wx',
214		});
215		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
216			flag: 'wx',
217		});
218		const receipt: WitnessAngularFactoriolabReceipt = {
219			schemaVersion: WITNESS_ANGULAR_FACTORIOLAB_SCHEMA,
220			result: 'pass',
221			fixture: ANGULAR_FACTORIOLAB_FIXTURE,
222			source: ANGULAR_FACTORIOLAB_SOURCE,
223			provenance,
224			canonicalReceipts,
225			runs,
226			mutation,
227			serviceWorker: WITNESS_ANGULAR_FACTORIOLAB_SERVICE_WORKER,
228			consoleErrors: WITNESS_ANGULAR_FACTORIOLAB_CONSOLE_ERRORS,
229			failedRequests: WITNESS_ANGULAR_FACTORIOLAB_FAILED_REQUESTS,
230			cancelledDuplicateFetches: {
231				category: WITNESS_ANGULAR_FACTORIOLAB_CANCELLED_DUPLICATE_FETCHES,
232				corroborationRule: WITNESS_CANCELLED_DUPLICATE_FETCH_RULE,
233				instances: runs.map((run) => ({
234					lane: run.lane,
235					pass: run.pass,
236					observed: run.cancelledDuplicateFetches.observed,
237					absent: run.cancelledDuplicateFetches.absent,
238					admitted: run.cancelledDuplicateFetches.admitted,
239				})),
240			},
241			scrollAbsence: runs[0]!.scrollAbsence,
242			buildLanes: {
243				baseline: {
244					angular: 'Angular 10.1',
245					builder: '@angular-devkit/build-angular:browser',
246					node: 'node 12.14.1 (darwin-x64 under Rosetta 2)',
247					distFiles: laneFileCounts.baseline,
248				},
249				migrated: {
250					angular: 'Angular 16.2',
251					builder: '@angular-devkit/build-angular:browser',
252					node: 'node 16.20.2 (darwin-arm64, native)',
253					distFiles: laneFileCounts.migrated,
254				},
255			},
256			persistence: {
257				plan: 'url-fragment-encoded',
258				preferences: 'browser-local-storage',
259				backend: 'none',
260				stubbed: false,
261				survivesOnlineReload: true,
262			},
263			readiness: {
264				angularLineage: { ready: 1, total: 4, counted: false },
265				overall: { ready: 3, total: 12 },
266			},
267			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
268			nonclaims: [
269				'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI, or `@angular-devkit/build-angular:browser` support.',
270				'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
271				'The production plan is solved inside the browser by the application itself against the Factorio 1.0 dataset it bundles; no backend exists, nothing was stubbed or seeded by the harness, and no request left the loopback origin successfully.',
272				'The saved state is written by the application into the browser’s own local storage under its own key; the harness neither writes nor reads that storage.',
273				'Scroll is not claimed. Every visited route was measured with the same generic viewport mechanism a scroll claim would use, and none of them produced a document taller than the 1280x720 viewport, because the application pins the body with `overflow: hidden` and scrolls its own panels. The settings panel does overflow its own box, and the driver scrolls it to bring a control into view; that is actionability, not a claimed scroll gesture, and it is not recorded as one.',
274				'Drag is not tested because the visited routes have no genuine drag surface.',
275				'Neither lane emits a single console error. That inventory is therefore empty, and empty is the strictest setting of that mechanism rather than a blanket allowance: any message at all lands outside the inventory and fails the run.',
276				'The exact failed-request inventory is empty in both lanes and every failed request still fails the run, with one named and corroborated exception that is a category rather than an allowance. The application points every one of its hundreds of `lab-icon` elements at the same 1x1 `assets/transparent.gif`, the bounded origin answers `cache-control: no-store`, and Angular re-renders the icon set when the bundled dataset resolves during bootstrap; the browser therefore has two identical fetches of that gif in flight and cancels one with `net::ERR_ABORTED`, intermittently. Only that exact path, method and reason is in the category, it carries no count, and an instance is admitted only when the same page also fetched the same path successfully in the same run — a cancelled fetch without a successful sibling fails the run, as does a cancelled fetch of any other path or with any other reason. Every admitted instance is recorded in the run and in this receipt with the successful fetches that corroborated it.',
277				'Neither build ships or registers a service worker. The browser context allowed registration and the application never attempted one, so the zero is the application’s own behavior rather than a policy imposed to produce it.',
278				'The one non-loopback seam the application carries is the Google Analytics tag in its own `index.html`. It is answered inside the browser context and never reaches a network, so it is neither a successful non-loopback request nor a failed one.',
279				'The two lanes emit different file names and different byte counts by construction, because the two builders hash their output differently. Byte parity across the lanes is not claimed here and is recorded separately by the bound build-parity receipt.',
280				'Locality is process-scoped and does not establish operating-system-wide isolation.',
281				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
282			],
283			integrity: { algorithm: 'sha256', canonicalDigest: '' },
284		};
285		receipt.integrity.canonicalDigest = witnessAngularFactoriolabDigest(receipt);
286		parseWitnessAngularFactoriolabReceipt(receipt);
287		await mkdir(witnessEvidence, { recursive: true });
288		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
289			flag: 'wx',
290		});
291		await writeFile(
292			join(witnessEvidence, 'receipt.md'),
293			renderWitnessAngularFactoriolabReceipt(receipt),
294			{ flag: 'wx' },
295		);
296		return receipt;
297	}
298	
299	export async function verifyWitnessAngularFactoriolab(
300		output = witnessEvidence,
301	): Promise<WitnessAngularFactoriolabReceipt> {
302		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
303		const receipt = parseWitnessAngularFactoriolabReceipt(
304			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
305		);
306		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
307			throw new Error('factoriolab linked Witness provenance differs');
308		for (const bound of receipt.canonicalReceipts)
309			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
310				throw new Error(`factoriolab bound build receipt bytes drifted: ${bound.path}`);
311		if (
312			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
313			renderWitnessAngularFactoriolabReceipt(receipt)
314		)
315			throw new Error('factoriolab human Witness receipt differs');
316		const serialized = canonicalize(receipt);
317		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
318			throw new Error('factoriolab receipt leaks host identity');
319		return receipt;
320	}
321	
322	export async function main(args = process.argv.slice(2)): Promise<void> {
323		const publishIndex = args.indexOf('--publish');
324		const verifyIndex = args.indexOf('--verify');
325		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
326			const output = resolve(root, args[publishIndex + 1]!);
327			if (output !== witnessEvidence) throw new Error('factoriolab publish path differs');
328			const receipt = await runWitnessAngularFactoriolab();
329			process.stdout.write(
330				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
331			);
332			return;
333		}
334		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
335			const receipt = await verifyWitnessAngularFactoriolab(resolve(root, args[verifyIndex + 1]!));
336			process.stdout.write(
337				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
338			);
339			return;
340		}
341		throw new Error(
342			'factoriolab Witness runner requires --run-twice --publish <dir> or --verify <dir>',
343		);
344	}
345	
346	if (basename(process.argv[1] ?? '') === 'angular-factoriolab-run.ts')
347		main().catch((error: unknown) => {
348			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
349			process.exitCode = 1;
350		});
