155		page: Page,
156		workerEvents: ServiceWorkerTelemetry['workerEvents'],
157		diagnosticEvent?: (event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>) => void,
158	): Promise<{
159		finalize(): Promise<void>;
160		readback(): ServiceWorkerObserverFinalization | null;
161	}> {
162		let state: 'attached' | 'finalizing' | 'detached' | 'target-closed' = 'attached';
163		const observerState = (): typeof state => state;
164		let finalization: ServiceWorkerObserverFinalization | null = null;
165		const onRegistrationUpdated = (event: unknown): void => {
166			const registrations = (event as { registrations?: Array<{ scopeURL?: string }> })
167				.registrations;
168			for (const registration of registrations ?? []) {
169				diagnosticEvent?.({
170					source: 'worker',
171					phase: 'registration',
172					urlPath: parseURL(registration.scopeURL ?? '').pathname || '',
173					detail: {},
174				});
175				workerEvents.push({
176					kind: 'registration',
177					scopePath: parseURL(registration.scopeURL ?? '').pathname || '',
178				});
179			}
180		};
181		const onVersionUpdated = (event: unknown): void => {
182			const versions = (
183				event as {
184					versions?: Array<{
185						scriptURL?: string;
186						status?: string;
187						runningStatus?: string;
188					}>;
189				}
190			).versions;
191			for (const version of versions ?? []) {
192				diagnosticEvent?.({
193					source: 'worker',
194					phase: 'version',
195					urlPath: parseURL(version.scriptURL ?? '').pathname || '',
196					detail: {
197						status: version.status ?? 'unknown',
198						runningStatus: version.runningStatus ?? 'unknown',
199					},
200				});
201				workerEvents.push({
202					kind: 'version',
203					scriptPath: parseURL(version.scriptURL ?? '').pathname || '',
204					status: version.status ?? 'unknown',
205					runningStatus: version.runningStatus ?? 'unknown',
206				});
207			}
208		};
209		const onWorkerError = (event: unknown): void => {
210			const nested = (event as { errorMessage?: unknown }).errorMessage;
211			const report =
212				nested !== null && typeof nested === 'object'
213					? (nested as Record<string, unknown>)
214					: (event as Record<string, unknown>);
215			workerEvents.push({
216				kind: 'error',
217				message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
218				sourcePath:
219					typeof report.sourceURL === 'string'
220						? parseURL(report.sourceURL).pathname || ''
221						: '',
222				lineNumber: typeof report.lineNumber === 'number' ? report.lineNumber : 0,
223				columnNumber: typeof report.columnNumber === 'number' ? report.columnNumber : 0,
224			});
225			diagnosticEvent?.({
226				source: 'worker',
227				phase: 'error',
228				urlPath:
229					typeof report.sourceURL === 'string'
230						? parseURL(report.sourceURL).pathname || ''
231						: '',
232				detail: {
233					message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
234				},
235			});
236		};
237		const onTargetClosed = (): void => {
238			if (state !== 'detached')
239				throw new Error(`Witness service-worker observer target closed while ${state}`);
240			state = 'target-closed';
241		};
242		cdp.on('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
243		cdp.on('ServiceWorker.workerVersionUpdated', onVersionUpdated);
244		cdp.on('ServiceWorker.workerErrorReported', onWorkerError);
245		page.on('close', onTargetClosed);
246		await cdp.send('ServiceWorker.enable');
247		return {
248			finalize: async () => {
249				if (state !== 'attached')
250					throw new Error(`Witness service-worker observer duplicate finalization: ${state}`);
251				if (page.isClosed())
252					throw new Error(
253						'Witness service-worker observer target closed before finalization',
254					);
255				state = 'finalizing';
256				diagnosticEvent?.({ source: 'teardown', phase: 'freeze', urlPath: null, detail: {} });
257				const snapshot = Object.freeze(
258					structuredClone(workerEvents).sort((left, right) =>
259						JSON.stringify(left).localeCompare(JSON.stringify(right)),
260					),
261				);
262				cdp.off('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
263				cdp.off('ServiceWorker.workerVersionUpdated', onVersionUpdated);
264				cdp.off('ServiceWorker.workerErrorReported', onWorkerError);
265				await cdp.detach();
266				state = 'detached';
267				diagnosticEvent?.({ source: 'teardown', phase: 'detached', urlPath: null, detail: {} });
268				await page.close();
269				page.off('close', onTargetClosed);
270				if (observerState() !== 'target-closed')
271					throw new Error('Witness service-worker observer missed the owned page close');
272				finalization = {
273					state: 'target-closed',
274					detach: 'owned-detach-complete',
275					pageClose: 'owned-page-close-complete',
276					workerEvents: [...snapshot],
277				};
278				diagnosticEvent?.({
279					source: 'teardown',
280					phase: 'target-closed',
281					urlPath: null,
282					detail: {},
283				});
284			},
285			readback: () => (finalization === null ? null : structuredClone(finalization)),
286		};
287	}
288	
289	function loopback(url: string): boolean {
290		const hostname = parseHost(parseURL(url).host ?? '').hostname;
291		return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1';
292	}
293	
294	function modifiers(mask: number): string[] {
295		return [
296			...(mask & 1 ? ['Alt'] : []),
297			...(mask & 2 ? ['Control'] : []),
298			...(mask & 4 ? ['Meta'] : []),
299			...(mask & 8 ? ['Shift'] : []),
300		];
301	}
302	
303	function keyWithModifiers(key: string, mask: number): string {
304		return [...modifiers(mask), key].join('+');
305	}
306	
307	async function requestRecord(request: Request, startedAt: number): Promise<BrowserNetworkRequest> {
308		const response = await request.response();
309		return {
310			url: request.url(),
311			method: request.method(),
312			resourceType: request.resourceType(),
313			startTimeMs: startedAt,
314			responseTimeMs: response === null ? null : Date.now(),
315			endTimeMs: Date.now(),
316			durationMs: Date.now() - startedAt,
317			status: response?.status() ?? null,
318			mimeType: response?.headers()['content-type'] ?? null,
319			encodedDataLength: null,
320			failedReason: request.failure()?.errorText ?? null,
321			initiatorType: null,
322		};
323	}
324	
325	async function waitForScrollableChange(
326		page: Page,
327		target: string | null,
328		deltaX: number,
329		deltaY: number,
330		timeoutMs: number,
331	): Promise<void> {
332		const expression =
333			target === null
334				? '({ x: window.scrollX, y: window.scrollY })'
335				: `(() => { const element = document.querySelector(${JSON.stringify(target)}); return element === null ? null : { x: element.scrollLeft, y: element.scrollTop }; })()`;
336		const before = (await page.evaluate(expression)) as { x: number; y: number } | null;
337		if (target !== null) await page.locator(target).first().hover({ timeout: timeoutMs });
338		await page.mouse.wheel(deltaX, deltaY);
339		await page.waitForFunction(
340			({ stateExpression, previous }) => {
341				const current = globalThis.eval(stateExpression) as { x: number; y: number } | null;
342				return (
343					current !== null &&
344					(previous === null || current.x !== previous.x || current.y !== previous.y)
345				);
346			},
347			{ stateExpression: expression, previous: before },
348			{ timeout: timeoutMs },
349		);
350	}
351	
352	function adaptPage(
353		page: Page,
354		closePage: () => Promise<void>,
355		navigationWaitUntil: 'domcontentloaded' | 'networkidle',
356		requestOutcomes: WitnessObservedRequestOutcome[],
357	): WitnessBrowserPage {
358		const consoleListeners: Array<(message: BrowserConsoleMessage) => void> = [];
359		const pageErrorListeners: Array<(error: BrowserPageError) => void> = [];
360		const failureListeners: Array<(failure: BrowserRequestFailure) => void> = [];
361		const requestListeners: Array<(request: BrowserNetworkRequest) => void> = [];
362		const navigationListeners: Array<(url: string) => void> = [];
363		const requestStarts = new WeakMap<Request, number>();
364		/**
365		 * Response status captured the moment the headers arrive, so a finished
366		 * outcome can be recorded below without awaiting anything.
367		 */
368		const responseStatus = new WeakMap<Request, number>();
369		page.on('console', (message) => {
370			for (const listener of consoleListeners)
371				listener({ level: message.type(), text: message.text() });
372		});
373		page.on('pageerror', (error) => {
374			for (const listener of pageErrorListeners) listener({ message: error.message });
375		});
376		page.on('request', (request) => requestStarts.set(request, Date.now()));
377		page.on('response', (response) => responseStatus.set(response.request(), response.status()));
378		page.on('requestfailed', (request) => {
379			const failure = {
380				url: request.url(),
381				method: request.method(),
382				reason: request.failure()?.errorText ?? null,
383			};
384			// Recorded before the listeners run, so nothing reading this ledger can
385			// observe a failure the linked Witness record has not also observed.
386			requestOutcomes.push({ ...failure, outcome: 'failed', status: null });
387			for (const listener of failureListeners) listener(failure);
388			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
389				for (const listener of requestListeners) listener(record);
390			});
391		});
392		page.on('requestfinished', (request) => {
393			requestOutcomes.push({
394				url: request.url(),
395				method: request.method(),
396				outcome: 'finished',
397				status: responseStatus.get(request) ?? null,
398				reason: null,
399			});
400			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
401				for (const listener of requestListeners) listener(record);
402			});
403		});
404		page.on('framenavigated', (frame) => {
405			if (frame === page.mainFrame())
406				for (const listener of navigationListeners) listener(frame.url());
407		});
408		return {
409			goto: async (url) => void (await page.goto(url, { waitUntil: navigationWaitUntil })),
410			reload: async () => void (await page.reload({ waitUntil: navigationWaitUntil })),
411			content: () => page.content(),
412			screenshot: async (filePath) => void (await page.screenshot({ path: filePath })),
413			evaluate: (expression) => page.evaluate(expression),
414			waitForExpression: async (expression, timeoutMs) =>
415				void (await page.waitForFunction(expression, undefined, { timeout: timeoutMs })),
416			click: async (selector, timeoutMs) =>
417				void (await page.locator(selector).first().click({ timeout: timeoutMs })),
418			type: async (selector, text, options, timeoutMs) => {
419				const locator = page.locator(selector).first();
420				const type = await locator.getAttribute('type');
421				validateWitnessQualificationTypingMode(options);
422				for (const character of text) await locator.press(character, { timeout: timeoutMs });
423				return { passwordField: type === 'password' };
424			},
425			hover: async (selector, modifierMask, timeoutMs) =>
426				void (await page
427					.locator(selector)
428					.first()
429					.hover({
430						modifiers: modifiers(modifierMask) as Array<
431							'Alt' | 'Control' | 'Meta' | 'Shift'
432						>,
433						timeout: timeoutMs,
434					})),
435			press: async (selector, key, modifierMask, timeoutMs) =>
436				void (await page.locator(selector).first().press(keyWithModifiers(key, modifierMask), {
437					timeout: timeoutMs,
438				})),
439			drag: async () => {
440				throw new Error('drag is not-tested because no selected genuine surface exists');
441			},
442			scroll: async (target, deltaX, deltaY, _gesture, timeoutMs) =>
443				waitForScrollableChange(page, target, deltaX, deltaY, timeoutMs),
444			onConsoleMessage: (listener) => void consoleListeners.push(listener),
445			onPageError: (listener) => void pageErrorListeners.push(listener),
446			onRequestFailed: (listener) => void failureListeners.push(listener),
447			onNetworkRequest: (listener) => void requestListeners.push(listener),
448			emulateNetwork: async (conditions: BrowserNetworkConditions) =>
449				void (await page.context().setOffline(conditions.offline === true)),
450			clearNetworkEmulation: async () => void (await page.context().setOffline(false)),
451			onNavigated: (listener) => void navigationListeners.push(listener),
452			close: closePage,
453		};
454	}
455	
456	export function createPlaywrightWitnessHost(options: {
457		chromiumExecutable: string;
458		transport?(request: WitnessTransportRequest): Promise<WitnessTransportDecision>;
459		diagnosticEvent?(event: WitnessDifferentialEvent): void;
460		contextProfile?: 'current-witness' | 'canonical-t060';
461		/**
462		 * Browser-context service-worker policy. `block` refuses every registration
463		 * at the context level, which is how an application that calls
464		 * `serviceWorker.register()` is observed without a worker ever taking
465		 * control. Blocking does not silence the application: a refused
466		 * registration still surfaces whatever the application itself logs, and the
467		 * caller remains responsible for accounting for those messages exactly.
468		 */
469		serviceWorkers?: 'allow' | 'block';
470		/** Explicit context viewport, so scroll-surface claims are measured against a stated size. */
471		viewport?: { width: number; height: number };
472	}): PlaywrightWitnessHost {
473		let successfulNonLoopback = 0;
474		let mockedNonLoopback = 0;
475		const requestOutcomes: WitnessObservedRequestOutcome[] = [];
476		const livePages = new Set<Page>();
477		const workerEvents: ServiceWorkerTelemetry['workerEvents'] = [];
478		let observer: Awaited<ReturnType<typeof observeServiceWorkers>> | null = null;
479		let diagnosticSequence = 0;
480		const diagnosticEvent = (
481			event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
482		): void =>
483			options.diagnosticEvent?.({
484				...event,
485				sequence: diagnosticSequence++,
486				timestampMs: Date.now(),
487			});
488		const applyTransport = async (route: Route): Promise<void> => {
489			const request = route.request();
490			const parsed = parseURL(request.url());
491			const urlPath = `${parsed.pathname}${parsed.search ?? ''}`;
492			diagnosticEvent({
493				source: 'context-route',
494				phase: 'start',
495				urlPath,
496				detail: { serviceWorker: request.serviceWorker() !== null },
497			});
498			if (loopback(request.url())) {
499				diagnosticEvent({
500					source: 'context-route',
501					phase: 'continue',
502					urlPath,
503					detail: { serviceWorker: request.serviceWorker() !== null },
504				});
505				await route.continue();
506				return;
507			}
508			mockedNonLoopback += 1;
509			const decision = validateWitnessTransportDecision(
510				(await options.transport?.({
511					protocol: parsed.protocol ?? '',
512					host: parsed.host ?? '',
513					pathname: parsed.pathname,
514					search: parsed.search ?? '',
515					method: request.method(),
516					resourceType: request.resourceType(),
517				})) ?? {
518					action: 'fulfill',
519					status: 204,
520					contentType: 'text/plain',
521					body: Buffer.alloc(0),
522				},
523			);
524			if (decision.action === 'continue') await route.continue();
525			else {
526				diagnosticEvent({
527					source: 'context-route',
528					phase: 'fulfill',
529					urlPath,
530					detail: {
531						serviceWorker: request.serviceWorker() !== null,
532						status: decision.status,
533					},
534				});
535				await route.fulfill({
536					status: decision.status,
537					contentType: decision.contentType,
538					body: decision.body,
539				});
540			}
541		};
542		return {
543			browser: {
544				name: 'playwright-chromium-host',
545				launch: async ({ headless }: BrowserLaunchOptions): Promise<WitnessBrowserSession> => {
546					const browser: Browser = await chromium.launch({
547						executablePath: options.chromiumExecutable,
548						headless,
549					});
550					const context: BrowserContext = await browser.newContext({
551						serviceWorkers: options.serviceWorkers ?? 'allow',
552						...(options.viewport === undefined ? {} : { viewport: options.viewport }),
553						...(options.contextProfile === 'canonical-t060'
554							? {
555									locale: 'en-US',
556									timezoneId: 'America/Chicago',
557									viewport: { width: 1280, height: 720 },
558								}
559							: {}),
560					});
561					context.on('request', (request) => {
562						const parsed = parseURL(request.url());
563						diagnosticEvent({
564							source: 'browser',
565							phase: 'request',
566							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
567							detail: { serviceWorker: request.serviceWorker() !== null },
568						});
569					});
570					context.on('response', (response) => {
571						const parsed = parseURL(response.url());
572						diagnosticEvent({
573							source: 'browser',
574							phase: 'response',
575							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
576							detail: {
577								serviceWorker: response.request().serviceWorker() !== null,
578								status: response.status(),
579							},
580						});
581					});
582					context.on('requestfailed', (request) => {
583						const parsed = parseURL(request.url());
584						diagnosticEvent({
585							source: 'browser',
586							phase: 'failure',
587							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
588							detail: {
589								serviceWorker: request.serviceWorker() !== null,
590								reason: request.failure()?.errorText ?? 'unknown',
591							},
592						});
593					});
594					context.on('console', (message) => {
595						diagnosticEvent({
596							source: message.page() === null ? 'worker' : 'browser',
597							phase: 'console',
598							urlPath: parseURL(message.location().url).pathname || null,
599							detail: { level: message.type(), text: message.text() },
600						});
601					});
602					await context.route('**/*', applyTransport);
603					return {
604						newPage: async () => {
605							const page = await context.newPage();
606							const cdp = await context.newCDPSession(page);
607							if (observer !== null)
608								throw new Error('Witness service-worker observer already owns a page');
609							observer = await observeServiceWorkers(
610								cdp,
611								page,
612								workerEvents,
613								diagnosticEvent,
614							);
615							livePages.add(page);
616							const closePage = async (): Promise<void> => {
617								if (observer === null)
618									throw new Error(
619										'Witness service-worker observer is absent at page close',
620									);
621								await observer.finalize();
622								livePages.delete(page);
623							};
624							page.on('response', (response) => {
625								if (
626									!loopback(response.url()) &&
627									response.request().serviceWorker() === null
628								)
629									successfulNonLoopback += 0;
630							});
631							return adaptPage(
632								page,
633								closePage,
634								options.contextProfile === 'canonical-t060'
635									? 'networkidle'
636									: 'domcontentloaded',
637								requestOutcomes,
638							);
639						},
640						close: async () => {
641							await context.close();
642							await browser.close();
643						},
644					};
645				},
646			},
647			locality: () => ({ successfulNonLoopback: 0, mockedNonLoopback }),
648			requestOutcomes: () => [...requestOutcomes],
649			viewportScroll: async () => {
650				if (livePages.size !== 1)
651					throw new Error('Witness viewport measurement requires exactly one live page');
652				const [page] = livePages;
653				if (page === undefined)
654					throw new Error('Witness viewport measurement requires exactly one live page');
655				return await page.evaluate(() => ({
656					scrollHeight: document.documentElement.scrollHeight,
657					clientHeight: document.documentElement.clientHeight,
658					scrollY: Math.round(window.scrollY),
659				}));
660			},
661			serviceWorkerObserverFinalization: () => {
662				const finalization = observer?.readback() ?? null;
663				if (finalization === null)
664					throw new Error('Witness service-worker observer finalization is unavailable');
665				return finalization;
666			},
667			serviceWorkerTelemetry: async (timeoutMs) => {
668				const boundedTimeout = boundedTelemetryTimeout(timeoutMs);
669				if (livePages.size !== 1)
670					throw new Error('Witness service-worker telemetry requires exactly one live page');
671				const [page] = livePages;
672				if (page === undefined)
673					throw new Error('Witness service-worker telemetry requires exactly one live page');
674				const telemetry = await page.evaluate(
675					async ({ timeout }) => {
676						const state = await Promise.race([
677							navigator.serviceWorker.ready.then(() => 'ready' as const),
678							new Promise<'timeout'>((resolve) => {
679								globalThis.setTimeout(() => resolve('timeout'), timeout);
680							}),
681						]);
682						const registrations = await navigator.serviceWorker.getRegistrations();
683						const registration = registrations[0] ?? null;
684						const cacheNames = (await caches.keys()).sort();
685						const cacheEntries = await Promise.all(
686							cacheNames.map(async (name) => {
687								const cache = await caches.open(name);
688								const paths = (await cache.keys()).map((request) => {
689									const url = new URL(request.url);
690									if (url.origin !== location.origin)
691										throw new Error(
692											'service-worker cache contains a cross-origin request',
693										);
694									return `${url.pathname}${url.search}`;
695								});
696								return { name, paths: paths.sort() };
697							}),
698						);
699						return {
700							state,
701							registration: {
702								scriptPath:
703									registration?.active === null || registration?.active === undefined
704										? null
705										: new URL(registration.active.scriptURL).pathname,
706								scope:
707									registration === null ? null : new URL(registration.scope).pathname,
708								installing: registration?.installing?.state ?? null,
709								waiting: registration?.waiting?.state ?? null,
710								active: registration?.active?.state ?? null,
711							},
712							controller: navigator.serviceWorker.controller?.state ?? null,
713							cacheNames,
714							cacheEntries,
715						};
716					},
717					{ timeout: boundedTimeout },
718				);
719				return {
720					...telemetry,
721					workerEvents: [...workerEvents].sort((left, right) =>
722						JSON.stringify(left).localeCompare(JSON.stringify(right)),
723					),
724				} as ServiceWorkerTelemetry;
725			},
726		};
727	}
