2391	function normalizedRecord(
2392		page: PageRecord,
2393		normalizeRoute: (path: string) => string = (path) => path,
2394		admittedCancelledDuplicates: ReadonlySet<string> = new Set(),
2395		origin = '',
2396	): WitnessRealAppRun['witnessRecord'] {
2397		return {
2398			interactions: page.interactions.map((interaction) => ({
2399				kind: interaction.kind as WitnessRealAppRun['interactions'][number]['kind'],
2400				selector:
2401					'selector' in interaction && typeof interaction.selector === 'string'
2402						? interaction.selector
2403						: 'viewport',
2404			})),
2405			navigationPaths: page.navigations.map((navigation) => {
2406				const parsed = parseURL(navigation.url);
2407				return normalizeRoute(`${parsed.pathname}${parsed.hash}`);
2408			}),
2409			trackedEventCounts: Object.fromEntries(
2410				Object.entries(page.trackedEvents).map(([name, events]) => [name, events.length]),
2411			),
2412			consoleErrors: page.consoleMessages.filter((message) => message.level === 'error').length,
2413			pageErrors: page.pageErrors.length,
2414			// Every browser-failed request except the ones the cancelled-duplicate
2415			// category admitted, which are recorded individually in their own
2416			// inventory. With no category declared the set is empty and this is the
2417			// plain total it has always been.
2418			failedRequests: page.failedRequests.filter(
2419				(request) =>
2420					!admittedCancelledDuplicates.has(
2421						failedRequestKey({
2422							method: request.method,
2423							path: originRelativePath(request.url, origin),
2424							reason: request.reason,
2425							count: 1,
2426						}),
2427					),
2428			).length,
2429		};
2430	}
