import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';
import { chromium } from 'playwright';

const root = '/Users/jacksm5pro/dev/open-source/versionless';
const lane = process.argv[2] === 'baseline'
	? join(root, '.versionless/cache/angular-jira-clone-baseline/rebuild/dist-1')
	: join(root, '.versionless/stage/angular-jira-clone-mj2/dist-a');
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);
const types: Record<string, string> = {
	'.html': 'text/html',
	'.js': 'text/javascript',
	'.css': 'text/css',
	'.json': 'application/json',
	'.png': 'image/png',
	'.gif': 'image/gif',
	'.txt': 'text/plain',
};

const server = createServer((request, response) => {
	void (async () => {
		const path = (request.url ?? '/').split('?')[0]!;
		let file = join(lane, path);
		let body: Buffer | null = null;
		try {
			body = await readFile(file);
		} catch {
			file = join(lane, 'index.html');
			body = await readFile(file);
		}
		response.writeHead(200, { 'content-type': types[extname(file)] ?? 'application/octet-stream' });
		response.end(body);
	})();
});
await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
const port = (server.address() as { port: number }).port;
const origin = `http://127.0.0.1:${port}`;

const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
const context = await browser.newContext({ viewport: { width: 1600, height: 900 } });
const nonLoopback: string[] = [];
await context.route('**/*', async (route) => {
	const url = route.request().url();
	if (url.startsWith(origin)) {
		await route.continue();
		return;
	}
	nonLoopback.push(`${route.request().method()} ${url}`);
	await route.fulfill({ status: 204, contentType: 'text/plain', body: '' });
});
const page = await context.newPage();
const consoleErrors: string[] = [];
const failed: string[] = [];
page.on('console', (message) => {
	if (message.type() === 'error') consoleErrors.push(message.text());
});
page.on('requestfailed', (request) =>
	failed.push(`${request.method()} ${request.url()} ${request.failure()?.errorText}`),
);
await page.goto(origin, { waitUntil: 'domcontentloaded' });
await page.waitForSelector('.board-dnd-list', { timeout: 20_000 });
await page.waitForTimeout(1500);

const columns = async (): Promise<unknown> =>
	await page.evaluate(() =>
		[...document.querySelectorAll('.board-dnd-list')].map((column) => ({
			header: column.querySelector('div.uppercase')?.textContent?.trim().replace(/\s+/g, ' '),
			dropId: column.querySelector('[cdkdroplist], .cdk-drop-list')?.id,
			cards: [...column.querySelectorAll('issue-card')].map(
				(card) => card.querySelector('p')?.textContent?.trim(),
			),
		})),
	);
console.log('COLUMNS', JSON.stringify(await columns(), null, 1));
console.log('URL', page.url());
console.log('BOARD HTML SAMPLE', (await page.evaluate(() => document.querySelector('.board-dnd-list')?.outerHTML.slice(0, 1500))));
console.log('NONLOOPBACK', JSON.stringify([...new Set(nonLoopback)], null, 1));
console.log('CONSOLE ERRORS', JSON.stringify(consoleErrors, null, 1));
console.log('FAILED', JSON.stringify(failed, null, 1));

await browser.close();
server.close();

