const port = server.address().port;
const origin = `http://127.0.0.1:${port}`;

const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
const context = await browser.newContext({ viewport: { width: 1600, height: 900 } });
const nonLoopback = [];
await context.route('**/*', async (route) => {
	const url = route.request().url();
	if (url.startsWith(origin)) {
		await route.continue();
		return;
	}
	nonLoopback.push(`${route.request().method()} ${url}`);
	await route.fulfill({ status: 204, contentType: 'text/plain', body: '' });
});
const page = await context.newPage();
const consoleErrors = [];
const failed = [];
page.on('console', (message) => {
	if (message.type() === 'error') consoleErrors.push(message.text());
});
page.on('requestfailed', (request) =>
	failed.push(`${request.method()} ${request.url()} ${request.failure()?.errorText}`),
);
await page.goto(origin, { waitUntil: 'domcontentloaded' });
await page.waitForSelector('.board-dnd-list', { timeout: 30000 });
await page.waitForTimeout(1500);

const columns = async () =>
	await page.evaluate(() =>
		[...document.querySelectorAll('.board-dnd-list')].map((column) => ({
			header: column.querySelector('div.uppercase')?.textContent?.trim().replace(/\s+/g, ' '),
			dropId: column.querySelector('.cdk-drop-list')?.id,
			cards: [...column.querySelectorAll('issue-card')].map(
				(card) => card.querySelector('p')?.textContent?.trim(),
			),
		})),
	);
console.log('LANE', laneName);
console.log('COLUMNS', JSON.stringify(await columns(), null, 1));
console.log('URL', page.url());
console.log('BOARD HTML SAMPLE', await page.evaluate(() => document.querySelector('.board-dnd-list')?.outerHTML.slice(0, 1200)));
console.log('NONLOOPBACK', JSON.stringify([...new Set(nonLoopback)], null, 1));
