console.log('FAILED', JSON.stringify(failed, null, 1));
console.log('SCROLL', JSON.stringify(await page.evaluate(() => ({ scrollHeight: document.documentElement.scrollHeight, clientHeight: document.documentElement.clientHeight }))));

await browser.close();
server.close();
