321			change: counts.change,
322			click: counts.click,
323			input: counts.input,
324			keydown: counts.keydown,
325			mouseover: `at-least-${WITNESS_ANGULAR_FACTORIOLAB_TRACKED_EVENTS.mouseoverAtLeast}-genuine-hovers`,
326		};
327	}
328	
329	/**
330	 * Lane-independent behavior projection.
331	 *
332	 * Production bytes are lane-specific by construction — the two builders hash
333	 * their output differently — so the byte inventory stays in the run record and
334	 * out of this digest. Everything the two lanes must agree on is in it: the same
335	 * gestures, the same assertions, the same URL-encoded route sequence, the same
336	 * empty error inventories, the same absent scroll surface, and the same zero
337	 * service-worker runtime.
338	 */
339	export function witnessAngularFactoriolabBehaviorDigest(
340		run: WitnessAngularFactoriolabRun | WitnessRealAppRun,
341	): string {
342		const zero = (run as WitnessAngularFactoriolabRun).zeroServiceWorker;
343		return sha256(
344			canonicalize({
345				app: run.app,
346				framework: run.framework,
347				interactions: run.interactions,
348				assertions: run.assertions,
349				routes: run.routes,
350				trackedEvents: run.trackedEvents,
351				witnessRecord: {
352					...run.witnessRecord,
353					trackedEventCounts: trackedEventProjection(run),
354				},
355				cleanPage: run.cleanPage,
356				offlineEvidence: run.offlineEvidence,
357				servedStaticPolicy: {
358					transport: run.servedStatic.transport,
359					documentFallback: run.servedStatic.documentFallback,
360					missingAssets: run.servedStatic.missingAssets,
361					traversal: run.servedStatic.traversal,
362					byteIdentical: run.servedStatic.byteIdentical,
363					hmrControls: run.servedStatic.hmrControls,
364					serviceWorkerScripts: run.servedStatic.serviceWorkers.length,
365				},
366				zeroServiceWorker: {
367					checkpoints: zero?.checkpoints,
368					outputFiles: zero?.outputFiles,
369					requests: zero?.requests,
370					workerEvents: zero?.workerEvents,
371				},
372				// Both inventories are empty in both lanes, so unlike an application
373				// whose lanes fail differently these participate whole rather than
374				// only by shape: an error appearing in one lane must break parity.
375				consoleErrorInventory: run.consoleErrorInventory,
376				failedRequestInventory: run.failedRequestInventory,
377				// The category, its rule and its membership must be identical in
378				// every lane and pass, so they participate whole. The observed
379				// instances deliberately do not: whether a given bootstrap lost the
380				// race is browser scheduling, and folding it into a parity digest
381				// would make the two lanes disagree about a fact that is not about
382				// the framework hop at all. Nothing is lost — every instance is
383				// recorded in the run and in the receipt, and the failed-request
384				// inventory above still accounts exactly for everything else.
385				cancelledDuplicateFetchCategory: {
386					policy: run.cancelledDuplicateFetches?.policy,
387					corroborationRule: run.cancelledDuplicateFetches?.corroborationRule,
388					category: run.cancelledDuplicateFetches?.category,
389					uncorroborated: run.cancelledDuplicateFetches?.uncorroborated,
390				},
391				scrollAbsence: run.scrollAbsence,
392				successfulNonLoopback: run.successfulNonLoopback,
393			}),
394		);
395	}
396	
397	export function witnessAngularFactoriolabDigest(
398		receipt: WitnessAngularFactoriolabReceipt,
399	): string {
400		const copy = structuredClone(receipt);
401		copy.integrity.canonicalDigest = '';
402		return sha256(canonicalize(copy));
403	}
404	
405	function assertZeroServiceWorker(
406		zero: WitnessAngularFactoriolabZeroServiceWorker | undefined,
407		label: string,
408	): void {
409		if (
410			zero === undefined ||
411			!exact(zero.outputFiles, []) ||
412			!exact(zero.requests, []) ||
413			!exact(zero.workerEvents, []) ||
414			!Array.isArray(zero.checkpoints) ||
415			zero.checkpoints.length !== 3 ||
416			!exact(
417				zero.checkpoints.map((checkpoint) => checkpoint.phase),
418				['before-interactions', 'after-interactions', 'after-online-reload'],
419			) ||
420			zero.checkpoints.some(
421				(checkpoint) =>
422					checkpoint.state !== 'timeout' ||
423					checkpoint.registrations !== 0 ||
424					checkpoint.controller !== null ||
425					checkpoint.cacheNames.length !== 0 ||
426					checkpoint.workerEvents.length !== 0,
427			)
428		)
429			throw new Error(`Angular factoriolab zero-service-worker evidence differs: ${label}`);
430	}
431	
432	function assertConsoleErrorInventory(
433		inventory: WitnessConsoleErrorInventory | undefined,
434		lane: 'baseline' | 'migrated',
435		label: string,
436	): void {
437		const pinned = WITNESS_ANGULAR_FACTORIOLAB_CONSOLE_ERRORS[lane].map((entry) => ({
438			message: entry.message,
439			count: entry.count,
440		}));
441		if (
442			inventory === undefined ||
443			inventory.policy !== 'exact-app-scoped-expected-console-errors' ||
444			inventory.originPlaceholder !== '{production-static-origin}' ||
445			!exact(inventory.outsideInventory, []) ||
446			!exact(inventory.expected, pinned) ||
447			!exact(inventory.observed, pinned) ||
448			inventory.total !== pinned.reduce((sum, entry) => sum + entry.count, 0)
449		)
450			throw new Error(`Angular factoriolab console-error inventory differs: ${label}`);
451	}
452	
453	function assertFailedRequestInventory(
454		inventory: WitnessFailedRequestInventory | undefined,
455		lane: 'baseline' | 'migrated',
456		label: string,
457	): void {
458		const pinned = WITNESS_ANGULAR_FACTORIOLAB_FAILED_REQUESTS[lane].map((entry) => ({
459			method: entry.method,
460			path: entry.path,
461			reason: entry.reason,
462			count: entry.count,
463		}));
464		if (
465			inventory === undefined ||
466			inventory.policy !== 'exact-app-scoped-expected-failed-requests' ||
467			!exact(inventory.outsideInventory, []) ||
468			!exact(inventory.expected, pinned) ||
469			!exact(inventory.observed, pinned) ||
470			inventory.total !== pinned.reduce((sum, entry) => sum + entry.count, 0)
471		)
472			throw new Error(`Angular factoriolab failed-request inventory differs: ${label}`);
473	}
474	
475	/**
476	 * The cancelled-duplicate-fetch category, checked as an accounting mechanism
477	 * rather than as a label.
478	 *
479	 * The declared membership must be exactly the pinned one, the rule carried in
480	 * the run must be the exact generic rule, and nothing may sit in
481	 * `uncorroborated`. Every observed instance must name a member of the category,
482	 * must have been cancelled at least once, and must carry at least one
483	 * corroborating successful fetch with a 2xx status — an instance recording zero
484	 * successes is precisely the case the rule refuses, so it fails here too.
485	 * Every member is accounted for: each one is either observed or explicitly
486	 * absent, never silently missing.
487	 */
488	function assertCancelledDuplicateFetches(
489		inventory: WitnessCancelledDuplicateFetchInventory | undefined,
490		lane: 'baseline' | 'migrated',
491		label: string,
492	): void {
493		const pinned = WITNESS_ANGULAR_FACTORIOLAB_CANCELLED_DUPLICATE_FETCHES[lane].map((entry) => ({
494			method: entry.method,
495			path: entry.path,
496			reason: entry.reason,
497		}));
498		const named = (entry: WitnessCancelledDuplicateFetchCategoryEntry): boolean =>
499			pinned.some(
500				(member) =>
501					member.method === entry.method &&
502					member.path === entry.path &&
503					member.reason === entry.reason,
504			);
505		if (
506			inventory === undefined ||
507			inventory.policy !== 'corroborated-browser-cancelled-duplicate-fetch' ||
508			inventory.corroborationRule !== WITNESS_CANCELLED_DUPLICATE_FETCH_RULE ||
509			!exact(inventory.category, pinned) ||
510			!exact(inventory.uncorroborated, []) ||
511			!Array.isArray(inventory.observed) ||
512			!Array.isArray(inventory.absent) ||
513			inventory.observed.length + inventory.absent.length !== pinned.length ||
514			inventory.observed.some(
515				(instance) =>
516					!named(instance) ||
517					instance.cancelled < 1 ||
518					instance.corroboratingSuccesses < 1 ||
519					instance.corroboratingStatuses.length === 0 ||
520					instance.corroboratingStatuses.some((status) => status < 200 || status >= 300),
521			) ||
522			inventory.absent.some((entry) => !named(entry)) ||
523			inventory.admitted !==
524				inventory.observed.reduce((sum, instance) => sum + instance.cancelled, 0)
525		)
526			throw new Error(`Angular factoriolab cancelled-duplicate-fetch category differs: ${label}`);
527	}
528	
529	/**
530	 * The scroll claim this vertical does not make, checked as strictly as one it
531	 * would: every visited route must be present, and every one of them must have
532	 * measured a document that does not overflow. A route whose `scrollHeight`
533	 * exceeded its `clientHeight` would mean a scroll surface existed and went
534	 * unexercised, which fails rather than passes quietly.
535	 */
536	function assertScrollAbsence(absence: WitnessMeasuredScrollAbsence | undefined, label: string): void {
537		if (
538			absence === undefined ||
539			absence.state !== 'measured-no-overflowing-document' ||
540			absence.claimed !== false ||
541			absence.viewport.width !== 1280 ||
542			absence.viewport.height !== 720 ||
543			absence.documentOverflow.length === 0 ||
544			!Array.isArray(absence.routes) ||
545			absence.routes.length < 3 ||
546			absence.routes.some(
547				(route) =>
548					route.route.length === 0 ||
549					route.clientHeight !== 720 ||
550					route.scrollHeight > route.clientHeight,
551			)
552		)
553			throw new Error(`Angular factoriolab scroll-absence measurement differs: ${label}`);
554	}
555	
556	/**
557	 * The receipt-level roll-up must reproduce the runs it summarizes exactly: one
558	 * entry per published run, each carrying that run's own observed and absent
559	 * members and its own admitted count. A summary that disagreed with the runs
560	 * would let a reader see a quieter story than the evidence tells.
561	 */
562	function assertCancelledDuplicateFetchRollup(receipt: WitnessAngularFactoriolabReceipt): void {
563		const rollup = receipt.cancelledDuplicateFetches;
564		if (
565			rollup === undefined ||
566			rollup.corroborationRule !== WITNESS_CANCELLED_DUPLICATE_FETCH_RULE ||
567			!exact(rollup.category, WITNESS_ANGULAR_FACTORIOLAB_CANCELLED_DUPLICATE_FETCHES) ||
568			!Array.isArray(rollup.instances) ||
569			rollup.instances.length !== receipt.runs.length ||
570			rollup.instances.some((instance, index) => {
571				const run = receipt.runs[index];
572				return (
573					run === undefined ||
574					instance.lane !== run.lane ||
575					instance.pass !== run.pass ||
576					!exact(instance.observed, run.cancelledDuplicateFetches?.observed) ||
577					!exact(instance.absent, run.cancelledDuplicateFetches?.absent) ||
578					instance.admitted !== run.cancelledDuplicateFetches?.admitted
579				);
580			})
581		)
582			throw new Error('Angular factoriolab cancelled-duplicate-fetch roll-up differs');
583	}
584	
585	export function parseWitnessAngularFactoriolabReceipt(
586		value: unknown,
587	): WitnessAngularFactoriolabReceipt {
588		if (value === null || typeof value !== 'object' || Array.isArray(value))
589			throw new Error('Angular factoriolab Witness receipt must be an object');
590		const receipt = value as WitnessAngularFactoriolabReceipt;
591		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
592		const behaviors = new Set<string>();
593		if (
594			receipt.schemaVersion !== WITNESS_ANGULAR_FACTORIOLAB_SCHEMA ||
595			receipt.result !== 'pass' ||
596			receipt.fixture !== ANGULAR_FACTORIOLAB_FIXTURE ||
597			!exact(receipt.source, ANGULAR_FACTORIOLAB_SOURCE) ||
598			!Array.isArray(receipt.canonicalReceipts) ||
599			receipt.canonicalReceipts.length !== ANGULAR_FACTORIOLAB_CANONICAL_RECEIPTS.length ||
600			receipt.canonicalReceipts.some((bound, index) => {
601				const pinned = ANGULAR_FACTORIOLAB_CANONICAL_RECEIPTS[index];
602				return (
603					pinned === undefined ||
604					bound.path !== pinned.path ||
605					bound.schemaVersion !== pinned.schemaVersion ||
606					bound.digest !== pinned.digest ||
607					bound.sha256 !== pinned.sha256
608				);
609			}) ||
610			!Array.isArray(receipt.runs) ||
611			receipt.runs.length !== 4
612		)
613			throw new Error('Angular factoriolab Witness binding differs');
614		for (const run of receipt.runs) {
615			const key = `${run.lane}:${run.pass}`;
616			if (
617				!expectedRuns.delete(key) ||
618				run.app !== 'angular-factoriolab' ||
619				run.framework !== 'angular' ||
620				run.result !== 'pass' ||
621				run.cleanPage !== true ||
622				run.successfulNonLoopback !== 0 ||
623				run.witnessRecord.pageErrors !== 0 ||
624				run.witnessRecord.consoleErrors !== 0 ||
625				run.witnessRecord.failedRequests !== 0 ||
626				run.offlineEvidence.state !== 'not-applicable' ||
627				run.observerFinalization.workerEvents.length !== 0 ||
628				run.servedStatic.serviceWorkers.length !== 0 ||
629				run.servedStatic.byteIdentical !== true ||
630				run.scrollSurface !== undefined ||
631				run.interactions.length === 0 ||
632				[...new Set(run.interactions.map((interaction) => interaction.kind))].sort().join(',') !==
633					'click,hover,press,type' ||
634				run.semanticDigest !== witnessAngularFactoriolabRawDigest(run) ||
635				run.behaviorDigest !== witnessAngularFactoriolabBehaviorDigest(run) ||
636				!exact(run.routes, WITNESS_ANGULAR_FACTORIOLAB_ROUTES)
637			)
638				throw new Error(`Angular factoriolab Witness run differs: ${key}`);
639			assertZeroServiceWorker(run.zeroServiceWorker, key);
640			assertConsoleErrorInventory(run.consoleErrorInventory, run.lane, key);
641			assertFailedRequestInventory(run.failedRequestInventory, run.lane, key);
642			assertCancelledDuplicateFetches(run.cancelledDuplicateFetches, run.lane, key);
643			assertScrollAbsence(run.scrollAbsence, key);
644			behaviors.add(run.behaviorDigest);
645		}
646		assertScrollAbsence(receipt.scrollAbsence, 'receipt');
647		assertCancelledDuplicateFetchRollup(receipt);
648		if (
649			expectedRuns.size !== 0 ||
650			behaviors.size !== 1 ||
651			!exact(receipt.consoleErrors, WITNESS_ANGULAR_FACTORIOLAB_CONSOLE_ERRORS) ||
652			!exact(receipt.failedRequests, WITNESS_ANGULAR_FACTORIOLAB_FAILED_REQUESTS) ||
653			!exact(receipt.serviceWorker, WITNESS_ANGULAR_FACTORIOLAB_SERVICE_WORKER) ||
654			receipt.buildLanes?.baseline?.distFiles !== 42 ||
655			receipt.buildLanes.migrated?.distFiles !== 39 ||
656			!exact(receipt.persistence, {
657				plan: 'url-fragment-encoded',
658				preferences: 'browser-local-storage',
659				backend: 'none',
660				stubbed: false,
661				survivesOnlineReload: true,
662			}) ||
663			receipt.mutation?.intendedFailure !== true ||
664			receipt.mutation.failure !== 'witness-semantic-assertion' ||
665			receipt.mutation.lane !== 'migrated' ||
666			receipt.mutation.seam.length === 0 ||
667			receipt.mutation.restoredByteIdentically !== true ||
668			receipt.mutation.restoredRun !== 'pass' ||
669			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
670			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
671			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
672			!exact(receipt.readiness, {
673				angularLineage: { ready: 1, total: 4, counted: false },
674				overall: { ready: 3, total: 12 },
675			}) ||
676			receipt.locality?.mode !== 'offline' ||
677			receipt.locality.successfulNonLoopback !== 0 ||
678			receipt.locality.osWideIsolation !== false ||
679			!Array.isArray(receipt.nonclaims) ||
680			receipt.nonclaims.length === 0 ||
681			receipt.integrity?.algorithm !== 'sha256' ||
682			receipt.integrity.canonicalDigest !== witnessAngularFactoriolabDigest(receipt)
683		)
684			throw new Error('Angular factoriolab Witness integrity differs');
685		return receipt;
686	}
687	
688	export function renderWitnessAngularFactoriolabReceipt(
689		receipt: WitnessAngularFactoriolabReceipt,
690	): string {
691		const boundReceipts = receipt.canonicalReceipts
692			.map((bound) => `\`${bound.path}\` (${bound.digest.slice(0, 12)})`)
693			.join(', ');
694		const routes = receipt.scrollAbsence.routes
695			.map((route) => `${route.route} ${route.scrollHeight}/${route.clientHeight}`)
696			.join(', ');
697		const cancelledCategory = receipt.cancelledDuplicateFetches.category.migrated
698			.map((entry) => `${entry.method} ${entry.path} (${entry.reason})`)
699			.join(', ');
700		const cancelledInstances = receipt.cancelledDuplicateFetches.instances
701			.map(
702				(instance) =>
703					`${instance.lane} pass ${instance.pass}: ${
704						instance.observed.length === 0
705							? 'no cancellation observed'
706							: instance.observed
707									.map(
708										(observedInstance) =>
709											`${observedInstance.cancelled} cancelled ${observedInstance.path}, corroborated by ${observedInstance.corroboratingSuccesses} successful fetch(es) with status ${observedInstance.corroboratingStatuses.join('/')}`,
710									)
711									.join('; ')
712					}`,
713			)
714			.join(' | ');
715		return `# factoriolab @5f54abb — direct Witness browser proof
716	
717	- Result: pass
718	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
719	- Runs: 2 baseline + 2 migrated production-static browser journeys
720	- Behavioral parity: ${receipt.runs[0]!.behaviorDigest}
721	- Build lanes: era ${receipt.buildLanes.baseline.angular} / ${receipt.buildLanes.baseline.builder} on ${receipt.buildLanes.baseline.node} (${receipt.buildLanes.baseline.distFiles} files) against migrated ${receipt.buildLanes.migrated.angular} / ${receipt.buildLanes.migrated.builder} on ${receipt.buildLanes.migrated.node} (${receipt.buildLanes.migrated.distFiles} files)
722	- Bound build receipts: ${boundReceipts}
723	- Journey: the era-pinned default production plan, an item swap through the icon picker with hovered tooltips, a typed output-rate edit the production table recomputes, a columns dialog that removes a column, the settings panel switching the display rate and saving a named state, the flow route, and an online reload the URL-encoded plan and the browser-local saved state both survive
724	- Persistence: plan ${receipt.persistence.plan}, preferences ${receipt.persistence.preferences}, backend ${receipt.persistence.backend}, stubbed: ${String(receipt.persistence.stubbed)}, survives an online reload: ${String(receipt.persistence.survivesOnlineReload)}
725	- Service worker: ${receipt.serviceWorker.state}; the context allowed registration and the application never attempted one, so zero registrations, controller, CacheStorage names and worker requests at three checkpoints in every pass
726	- Console-error inventory (exact, whole journey, per lane): empty in both lanes — both builds are genuinely silent, and any error at all fails the run
727	- Failed-request inventory (exact, whole journey, per lane): empty in both lanes, once the cancelled-duplicate category below has taken its own instances; every other failed request still fails the run
728	- Cancelled-duplicate-fetch category (both lanes): ${cancelledCategory} — pinned by path, method and browser reason, never by count. ${receipt.cancelledDuplicateFetches.corroborationRule}
729	- Cancelled-duplicate-fetch instances as published: ${cancelledInstances}
730	- Mutation proof: \`${receipt.mutation.seam}\` in \`${receipt.mutation.path}\` at offset ${receipt.mutation.offset} made the journey red, byte-identical restoration made it green again
731	- Scroll: ${receipt.scrollAbsence.state} — ${receipt.scrollAbsence.documentOverflow}; measured scrollHeight/clientHeight per visited route at ${receipt.scrollAbsence.viewport.width}x${receipt.scrollAbsence.viewport.height}: ${routes}
732	- Angular lineage readiness: unchanged at ${receipt.readiness.angularLineage.ready}/${receipt.readiness.angularLineage.total}; this vertical is not counted
733	
734	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
735	`;
736	}
737	
738	export function witnessAngularFactoriolabAggregateMember(digestValue: string) {
739		return {
740			id: 'witness-angular-factoriolab',
741			framework: 'angular',
742			track: 'production-readiness-direct-witness-angular10-to-angular16-browser-builder',
743			bundler: 'angular-cli-10.1-browser-builder-to-angular-16.2-browser-builder',
744			runtime: 'node-12.14.1-to-node-16.20.2',
745			result: 'pass',
746			receipt: WITNESS_ANGULAR_FACTORIOLAB_RECEIPT_PATH,
747			digest: digestValue,
748		};
749	}
750	
751	export async function verifyWitnessAngularFactoriolabEvidence(rootDir = '.') {
752		const root = resolve(rootDir);
753		const receiptPath = join(root, WITNESS_ANGULAR_FACTORIOLAB_RECEIPT_PATH);
754		const receipt = parseWitnessAngularFactoriolabReceipt(
755			JSON.parse(await readFile(receiptPath, 'utf8')),
756		);
757		for (const bound of receipt.canonicalReceipts) {
758			const bytes = await readFile(join(root, bound.path));
759			if (sha256(bytes) !== bound.sha256)
760				throw new Error(`Angular factoriolab bound build receipt bytes drifted: ${bound.path}`);
761			const parsed = JSON.parse(bytes.toString('utf8')) as {
762				schemaVersion?: unknown;
763				digest?: unknown;
764			};
765			if (parsed.schemaVersion !== bound.schemaVersion || parsed.digest !== bound.digest)
766				throw new Error(`Angular factoriolab bound build receipt identity differs: ${bound.path}`);
767		}
768		if (
769			(await readFile(join(dirname(receiptPath), 'receipt.md'), 'utf8')) !==
770			renderWitnessAngularFactoriolabReceipt(receipt)
771		)
772			throw new Error('Angular factoriolab human Witness receipt differs');
773		return {
774			valid: true as const,
775			digest: receipt.integrity.canonicalDigest,
776			artifacts: 0,
777			receipt,
778		};
779	}
